style.css:
@-moz-document domain("grok.com") {
/* ============================================
     SPACEX MISSION CONTROL THEME FOR GROK.COM
     Background: SpaceX Iridium-4 Night Launch
     (Public Domain — SpaceX Official Flickr)
     ============================================ */

  /* === ROOT BODY: Space Background === */
  body, html {
    background-color: #020a14 !important;
    background-image:
      linear-gradient(
        rgba(2, 10, 20, 0.72),
        rgba(2, 10, 20, 0.72)
      ),
      url('https://live.staticflickr.com/4520/38013829542_b382e2bb9a_k.jpg') !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
    font-family: 'Inter', 'SF Pro Display', -apple-system, sans-serif !important;
    color: #d0e8f8 !important;
  }

  /* === MAIN APP WRAPPER === */
  #__next,
  [data-testid="root"],
  main,
  div[class*="layout"],
  div[class*="container"],
  div[class*="wrapper"],
  div[class*="page"] {
    background: transparent !important;
  }

  /* === LEFT SIDEBAR / NAV === */
  nav,
  aside,
  div[class*="sidebar"],
  div[class*="Sidebar"],
  div[class*="nav"],
  div[class*="Nav"] {
    background: rgba(2, 14, 28, 0.82) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border-right: 1px solid rgba(0, 210, 255, 0.18) !important;
    box-shadow: 2px 0 24px rgba(0, 150, 220, 0.08) !important;
  }

  /* === SIDEBAR ICONS & LINKS === */
  nav a,
  nav button,
  aside a,
  aside button {
    color: #7fc8e8 !important;
    transition: color 0.2s, background 0.2s !important;
  }

  nav a:hover,
  nav button:hover,
  aside a:hover,
  aside button:hover {
    color: #00d2ff !important;
    background: rgba(0, 210, 255, 0.09) !important;
    border-radius: 8px !important;
  }

  /* === HEADER / TOP BAR === */
  header,
  div[class*="header"],
  div[class*="Header"],
  div[class*="topbar"],
  div[class*="Topbar"] {
    background: rgba(3, 12, 24, 0.7) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border-bottom: 1px solid rgba(0, 210, 255, 0.13) !important;
  }

  /* === HEADER LINKS (Imagine, Private) === */
  header a,
  header button {
    color: #7fc8e8 !important;
  }

  header a:hover,
  header button:hover {
    color: #00d2ff !important;
    text-shadow: 0 0 8px rgba(0, 210, 255, 0.6) !important;
  }

  /* === MAIN CONTENT AREA === */
  div[class*="main"],
  div[class*="content"],
  div[class*="chat"],
  div[class*="Chat"],
  div[class*="messages"],
  div[class*="Messages"] {
    background: transparent !important;
  }

  /* === CENTER HERO TITLE (SuperGrok) === */
  h1, h2, h3, h4, h5, h6 {
    color: #e8f4ff !important;
    text-shadow: 0 0 20px rgba(0, 180, 255, 0.3) !important;
    letter-spacing: 0.03em !important;
  }

  /* === INPUT / CHAT BOX === */
  textarea,
  input[type="text"],
  input[type="search"],
  div[contenteditable="true"],
  div[class*="input"],
  div[class*="Input"],
  div[class*="textbox"],
  div[class*="Textbox"] {
    background: rgba(4, 18, 36, 0.88) !important;
    color: #c8e8ff !important;
    border: 1px solid rgba(0, 200, 255, 0.3) !important;
    border-radius: 12px !important;
    box-shadow:
      0 0 0 1px rgba(0, 180, 255, 0.12),
      0 0 20px rgba(0, 150, 255, 0.08),
      inset 0 1px 0 rgba(255,255,255,0.04) !important;
    caret-color: #00d2ff !important;
    transition: border-color 0.25s, box-shadow 0.25s !important;
  }

  textarea:focus,
  input:focus,
  div[contenteditable="true"]:focus {
    border-color: rgba(0, 210, 255, 0.6) !important;
    box-shadow:
      0 0 0 2px rgba(0, 200, 255, 0.15),
      0 0 30px rgba(0, 170, 255, 0.18) !important;
    outline: none !important;
  }

  /* === PROMPT INPUT WRAPPER === */
  form,
  div[class*="prompt"],
  div[class*="Prompt"],
  div[class*="inputWrapper"],
  div[class*="InputWrapper"] {
    background: rgba(4, 16, 32, 0.78) !important;
    border: 1px solid rgba(0, 190, 255, 0.2) !important;
    border-radius: 16px !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    box-shadow:
      0 4px 32px rgba(0, 120, 220, 0.12),
      0 1px 0 rgba(0, 200, 255, 0.06) inset !important;
  }

  /* === BUTTONS === */
  button {
    color: #a0d8f0 !important;
    transition: all 0.2s ease !important;
  }

  /* Primary action buttons */
  button[class*="primary"],
  button[class*="submit"],
  button[class*="send"],
  button[class*="Send"],
  button[type="submit"] {
    background: linear-gradient(135deg, #003d6b 0%, #005f99 50%, #0080cc 100%) !important;
    color: #e0f4ff !important;
    border: 1px solid rgba(0, 200, 255, 0.4) !important;
    border-radius: 10px !important;
    box-shadow: 0 0 16px rgba(0, 150, 255, 0.25) !important;
  }

  button[class*="primary"]:hover,
  button[type="submit"]:hover {
    background: linear-gradient(135deg, #005080 0%, #007acc 100%) !important;
    box-shadow: 0 0 24px rgba(0, 180, 255, 0.4) !important;
  }

  /* Voice / icon buttons */
  button[aria-label*="voice"],
  button[aria-label*="Voice"],
  button[aria-label*="Dictation"],
  button[aria-label*="record"] {
    background: rgba(0, 80, 140, 0.5) !important;
    border: 1px solid rgba(0, 200, 255, 0.35) !important;
    border-radius: 50% !important;
    box-shadow: 0 0 12px rgba(0, 160, 255, 0.3) !important;
  }

  /* === MODEL SELECT PILL === */
  button[id*="model"],
  div[id*="model"] {
    background: rgba(0, 30, 60, 0.7) !important;
    border: 1px solid rgba(0, 180, 255, 0.25) !important;
    border-radius: 20px !important;
    color: #60c8f0 !important;
  }

  /* === CHAT MESSAGES === */
  div[class*="message"],
  div[class*="Message"],
  div[class*="turn"],
  div[class*="Turn"],
  article {
    background: rgba(4, 16, 32, 0.65) !important;
    border: 1px solid rgba(0, 160, 230, 0.1) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    margin-bottom: 4px !important;
    color: #cce8ff !important;
  }

  /* === USER MESSAGE BUBBLE === */
  div[class*="userMessage"],
  div[class*="user-message"],
  div[class*="human"] {
    background: rgba(0, 50, 100, 0.55) !important;
    border-left: 3px solid #00a8e8 !important;
  }

  /* === AI RESPONSE BUBBLE === */
  div[class*="assistantMessage"],
  div[class*="assistant-message"],
  div[class*="ai"],
  div[class*="bot"] {
    background: rgba(2, 20, 40, 0.6) !important;
    border-left: 3px solid rgba(0, 200, 255, 0.3) !important;
  }

  /* === SCROLLBAR STYLING === */
  ::-webkit-scrollbar {
    width: 6px !important;
    height: 6px !important;
  }

  ::-webkit-scrollbar-track {
    background: rgba(0, 10, 25, 0.5) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: rgba(0, 140, 200, 0.4) !important;
    border-radius: 4px !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 200, 255, 0.6) !important;
  }

  /* === LINKS === */
  a {
    color: #39b8e8 !important;
    text-decoration: none !important;
  }

  a:hover {
    color: #00d2ff !important;
    text-shadow: 0 0 8px rgba(0, 210, 255, 0.4) !important;
  }

  /* === CODE BLOCKS === */
  pre, code {
    background: rgba(0, 15, 35, 0.85) !important;
    border: 1px solid rgba(0, 180, 255, 0.15) !important;
    border-radius: 8px !important;
    color: #7fe8cc !important;
    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace !important;
  }

  /* === DROPDOWN / MENU PANELS === */
  div[role="menu"],
  div[role="listbox"],
  div[role="dialog"],
  div[class*="dropdown"],
  div[class*="Dropdown"],
  div[class*="popover"],
  div[class*="Popover"],
  div[class*="modal"],
  div[class*="Modal"] {
    background: rgba(4, 16, 36, 0.95) !important;
    border: 1px solid rgba(0, 190, 255, 0.22) !important;
    border-radius: 12px !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    box-shadow: 0 8px 40px rgba(0, 100, 200, 0.25) !important;
    color: #c0e0f8 !important;
  }

  /* === PLACEHOLDER TEXT === */
  ::placeholder {
    color: rgba(120, 180, 220, 0.45) !important;
    font-style: italic !important;
  }

  /* === SELECTION === */
  ::selection {
    background: rgba(0, 160, 255, 0.28) !important;
    color: #ffffff !important;
  }

  /* === SUBTLE STAR-FIELD OVERLAY via pseudo on body === */
  /* (Done via semi-transparent overlay on the bg image above) */

  /* === FOOTER / BOTTOM BAR === */
  footer,
  div[class*="footer"],
  div[class*="Footer"] {
    background: rgba(2, 10, 22, 0.8) !important;
    border-top: 1px solid rgba(0, 180, 255, 0.1) !important;
    color: #6090b0 !important;
  }

  /* === TOOLTIPS === */
  div[role="tooltip"],
  span[role="tooltip"] {
    background: rgba(0, 30, 60, 0.95) !important;
    border: 1px solid rgba(0, 180, 255, 0.3) !important;
    color: #a0d8f8 !important;
    border-radius: 6px !important;
  }

  /* === UPLOAD / ATTACH BUTTON === */
  button[aria-label*="Attach"],
  button[aria-label*="attach"],
  label[class*="attach"],
  label[class*="upload"] {
    color: #5ab8e0 !important;
  }

  /* === IMAGINE / PRIVATE PILL BUTTONS (top right) === */
  header a[href*="imagine"],
  header a[href*="private"] {
    background: rgba(0, 40, 80, 0.6) !important;
    border: 1px solid rgba(0, 190, 255, 0.3) !important;
    border-radius: 20px !important;
    padding: 4px 14px !important;
    color: #78ccf0 !important;
  }

  header a[href*="imagine"]:hover,
  header a[href*="private"]:hover {
    background: rgba(0, 70, 130, 0.7) !important;
    border-color: rgba(0, 220, 255, 0.5) !important;
    box-shadow: 0 0 14px rgba(0, 180, 255, 0.3) !important;
    color: #00d2ff !important;
  }
}
